SELECT (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='bk_customer' AND table_name='customer_listing_inquiry' AND column_name IN ('id','customer_id','listing_id','broker_id','inquiry_channel','inquiry_content','status','validation_state','checked_listing_version','checked_at','created_at','updated_at','deleted'))=13 AND (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='bk_customer' AND table_name='customer_follow_record' AND column_name='inquiry_id')=1 AND (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='bk_customer' AND table_name='customer_inquiry_command_receipt' AND column_name IN ('actor_user_id','operation','request_id','request_hash','inquiry_id','status','created_at'))=7 AND (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='bk_customer' AND table_name IN ('customer_listing_inquiry','customer_inquiry_command_receipt') AND engine='InnoDB')=2;
